int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    if (tolen < 1) {
        return -EINVAL;
    }

    while (i < fromlen) {
        if (j >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        switch (from[i]) {
            case SLASH:
                to[j++] = '/';
                i++;
                break;
            case SYMLINK:
                if (i + 1 > fromlen) {
                    return -EFAULT;
                }
                i += 2;
                break;
            case DIR:
                if (i + 1 > fromlen) {
                    return -EFAULT;
                }
                i += 2;
                break;
            default:
                while (i < fromlen) {
                    if (j >= tolen - 1) {
                        return -ENAMETOOLONG;
                    }
                    to[j++] = from[i++];
                    if (i < fromlen && from[i] == '\0') {
                        break;
                    }
                }
                break;
        }
    }

    to[j] = '\0';
    return 0;
}

int path_to_user(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    int j = 0;
    unsigned char *p = from;
    int component_len;
    int error;

    for (i = 0; i < fromlen; i += component_len) {
        if (j >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        component_len = from[i];

        if (component_len == 0) {
            to[j++] = '.';
        } else if (component_len == 1 && i + component_len > fromlen) {
            if (j == 0) {
                to[j++] = '.';
            } else {
                to[j++] = '.';
                to[j++] = '.';
            }
        } else {
            int k;
