int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    int i = 0;

    while (i < fromlen) {
        if (pos >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        if (from[i] == PATH_COMPONENT_TYPE_SYMLINK) {
            if (pos + 7 >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '(';
            to[pos++] = 's';
            to[pos++] = 'y';
            to[pos++] = 'm';
            to[pos++] = 'l';
            to[pos++] = 'i';
            to[pos++] = 'n';
            to[pos++] = 'k';
            to[pos++] = ')';
            i++;
        } else if (from[i] == PATH_COMPONENT_TYPE_DIR) {
            if (pos + 2 >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '[';
            to[pos++] = ']';
            i++;
        } else {
            int length = from[i];
            if (i + length > fromlen) {
                return -EINVAL;
            }
            if (pos + length >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            for (int j = 0; j < length; j++) {
                to[pos++] = from[i + 1 + j];
            }
            i += length + 1;
        }

        if (i < fromlen) {
            if (pos + 1 >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '/';
        }
    }

    to[pos] = '\0';
    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    if (tolen <= 0)
        return -EINVAL;

    while (i < fromlen) {
        if (j + 1 >= tolen)
            return -ENAMETOOLONG;

        if (from[i] == '/') {
            to[j++] = '/';
            i++;
            continue;
        }

        if (from[i] == '\0') {
            to[j++] = '\0';
            i++;
            continue;
        }

        if (j + 1 >= tolen)
            return -ENAMETOOLONG;

        to[j++] = from[i++];
    }

    if (j + 1 >= tolen)
        return -ENAMETOOLONG;

    to[j] = '\0';
    return 0;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j;

    for (i = 0, j = 0; i < fromlen && j < tolen - 1; i++) {
        if (from[i] == '/') {
            // Handle directory indicator
            to[j++] = '/';
            // Skip consecutive slashes
            while (i + 1 < fromlen && from[i + 1] == '/') {
                i++;
            }
        } else if (from[i] == '.') {
            // Handle current directory
            to[j++] = '.';
        } else if (from[i] == '~') {
            // Handle symlink
            if (j + 1 < tolen) {
                to[j++] = '.';
                to[j++] = '.';
            } else {
                return -ENAMETOOLONG;
            }
        } else {
            // Handle regular filename character
            to[j++] = from[i];
        }
    }

    // Ensure null-termination
    if (j < tolen) {
        to[j] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}
